<script setup lang="ts">
import RecordSelect from '../components/RecordSelect.vue'
import {computed,ref} from 'vue'
import {useAuth} from '../stores/auth'
import type {Row} from '../api/types'
import {useResource,today} from '../composables/useResource'
import {usePagedResource} from '../composables/usePagedResource'
import ExchangeActions from '../components/ExchangeActions.vue'
import PageHeader from '../components/PageHeader.vue'
import ResourceState from '../components/ResourceState.vue'
import DataTable from '../components/DataTable.vue'
import EntityDialog,{type Field} from '../components/EntityDialog.vue'
const auth=useAuth(),project=ref<any>(''),listing=usePagedResource(()=>`/records/cost-overview?project_id=${project.value}`),{data,loading,error,paging,onPage,onSize,onSearch}=listing,expenseList=usePagedResource(()=>`/records/expenses?project_id=${project.value}`),dialog=ref(false),tab=ref('overview')
const overview=computed(()=>data.value),expenses=expenseList.data
async function load(){await Promise.all([listing.load(),expenseList.load()])}
const fields=computed<Field[]>(()=>[{key:'project_id',label:'所属项目',kind:'select',required:true,options:auth.catalog.projects.map(p=>({label:p.name,value:p.id}))},{key:'category',label:'费用类型',kind:'select',required:true,options:[{label:'人工费用',value:'LABOR'},{label:'机械费用',value:'MACHINE'},{label:'分包费用',value:'SUBCONTRACT'},{label:'其他费用',value:'OTHER'}]},{key:'amount',label:'发生金额（元）',kind:'money',required:true},{key:'incurred_date',label:'发生日期',kind:'date',required:true},{key:'description',label:'费用说明',kind:'textarea',required:true,span:2}])
</script>
<template><PageHeader title="成本费用" subtitle="归集人工、机械、分包及其他费用，材料成本由真实领料自动入账。"><ExchangeActions :entity="tab==='overview'?'cost-overview':'expenses'" :filters="{project_id:project,q:tab==='overview'?paging.q:expenseList.paging.q}"/><el-button :loading="loading" @click="load">刷新</el-button><el-button v-if="auth.can('cost:write')" type="primary" @click="dialog=true">＋ 登记费用</el-button></PageHeader><div class="notice-strip">成本口径 <span>领料材料成本 + 人工 + 机械 + 分包 + 其他</span><b>采购入库不直接计入项目消耗成本</b></div><section class="panel table-panel"><div class="section-toolbar"><RecordSelect v-model="project" placeholder="全部项目" style="width:260px" entity="projects"/></div><ResourceState :error="error" :loading="loading" @retry="load"><el-tabs v-model="tab"><el-tab-pane label="项目成本总览" name="overview"><DataTable :remote="paging" @page="onPage" @size="onSize" @search="onSearch" :rows="overview" :columns="[{key:'name',label:'项目名称',minWidth:200},{key:'budget_amount',label:'项目预算（元）',money:true,minWidth:160},{key:'material_cost',label:'领料材料成本（元）',money:true,minWidth:170},{key:'other_cost',label:'其他费用（元）',money:true,minWidth:150},{key:'actual_cost',label:'实际总成本（元）',money:true,minWidth:160},{key:'budget_usage',label:'预算使用率（%）',number:true,minWidth:160},{key:'registered_cost_balance',label:'合同额减已登记成本（元）',money:true,minWidth:160}]"/></el-tab-pane><el-tab-pane label="费用登记明细" name="expenses"><DataTable :remote="expenseList.paging" @page="expenseList.onPage" @size="expenseList.onSize" @search="expenseList.onSearch" :rows="expenses" :columns="[{key:'project_name',label:'项目名称',minWidth:210},{key:'category',label:'费用类型',status:true,width:120},{key:'description',label:'费用说明',minWidth:220},{key:'amount',label:'发生金额（元）',money:true,minWidth:150},{key:'incurred_date',label:'发生日期',width:130},{key:'operator_name',label:'经办人'},{key:'created_at',label:'登记时间',date:true,minWidth:170}]"/></el-tab-pane></el-tabs></ResourceState></section><EntityDialog v-model="dialog" title="登记项目成本费用" endpoint="/costs" :fields="fields" :defaults="{incurred_date:today(),category:'OTHER'}" @saved="load"/></template>
